public class DataComponentWrapper {
	public static final Map<DataComponentType<?>, ComponentMapping<?>> MAP = new HashMap<>();

	public static void register(DataComponentType<?> type, ComponentMapping<?> mapping) {
		MAP.put(type, new ComponentMapping(type, mapping));
	}

	public static <T> ComponentMapping<T> wrapType(DataComponentType<T> type) {
		return (ComponentMapping<T>) MAP.get(type);
	}

	public static <T> T wrapValue(DataComponentType<T> type, Object value) {
		var mapping = wrapType(type);
		if (mapping != null) {
			return mapping.wrapValue(value);
		}
		return (T) value;
	}

	record ComponentMapping<T>(DataComponentType<T> type, ComponentWrapper<T> wrapper) {
		public T wrapValue(Object o) {
			return wrapper.fromJS(o);
		}

		public Object unwrapValue(Object o) {
			return wrapper.toJS(type, o);
		}
	}
}
